":"opt-extra-bacon","option_group_id":"og-extras","name":"Tiras Extras de Bacon Defumado Crocante","price_delta_cents":650,"is_available":true,"sort_order":1},{"id":"opt-extra-cheese","option_group_id":"og-extras","name":"Dobro de Queijo Cheddar Inglês","price_delta_cents":550,"is_available":true,"sort_order":2},{"id":"opt-extra-patty","option_group_id":"og-extras","name":"Blend Bovino Extra de 200g","price_delta_cents":1400,"is_available":true,"sort_order":3},{"id":"opt-extra-onion","option_group_id":"og-extras","name":"Cebola Caramelizada na Cerveja Preta","price_delta_cents":400,"is_available":true,"sort_order":4}]}]'::jsonb) ON CONFLICT (id) DO NOTHING;
